# three digits: regroup the lowest short unit; a zero digit forces a regroup from above; hundreds suffice
def regroup(top, bot):
    t = [top // 100, top // 10 % 10, top % 10]; s = [bot // 100, bot // 10 % 10, bot % 10]
    for i in (2, 1):
        if t[i] < s[i]:
            if t[i - 1] == 0:
                assert i == 2 and t[0] >= 1
                t[0] -= 1; t[1] += 10
            t[i - 1] -= 1; t[i] += 10
    return t, s
for top in range(1000):
    for bot in range(top + 1):
        t, s = regroup(top, bot)
        assert 100 * t[0] + 10 * t[1] + t[2] == top
        assert t[1] >= s[1] and t[2] >= s[2] and t[1] - s[1] <= 9 and t[2] - s[2] <= 9 and t[0] >= s[0]
        assert 100 * (t[0] - s[0]) + 10 * (t[1] - s[1]) + (t[2] - s[2]) == top - bot
        assert 10 * t[1] + t[2] - (10 * s[1] + s[2]) <= 99
