def carries(nums):
    out, c = [], 0
    for i in range(6):
        t = sum(x // 10**i % 10 for x in nums) + c
        c = t // 10; out.append(c)
    return out
import itertools
for nums in itertools.product([0, 9, 19, 99, 999, 909, 990], repeat=3):
    assert max(carries(nums)) <= 2
